+/// The `gh` command word, past any inherited flags given before it
+/// (`gh -R o/r secret set ...`). `-R`/`--repo` take a value.
+fn command_word(args: &[String]) -> Option<&str> {
+    let mut i = 0;
+    while let Some(a) = args.get(i) {
+        let a = a.as_str();
+        if a == "-R" || a == "--repo" {
+            i += 2;
+        } else if a.starts_with('-') {
+            i += 1;
+        } else {
+            return Some(a);
+        }
+    }
+    None
+}
